@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Country {
  + VATRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + SSN : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Product "*" -- "1" Country : manufacturedIn
Product "*" -- "1" Representative : distributedBy
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "*" Country : resellsIn
Representative "1" -- "*" Order : places
Order "*" -- "1" Product
Order "*" -- "1" Customer

@enduml

